import React, { useState } from 'react';

const AuthButtons = () => {
    // Временный стейт для проверки залогинен ли пользователь
    const [isLoggedIn, setIsLoggedIn] = useState(false);

    // Временные данные пользователя (потом будут с API)
    const [user, setUser] = useState({
        name: 'Иван Петров',
        avatar: 'https://via.placeholder.com/40'
    });

    // Функции-заглушки (потом заменишь на реальные API вызовы)
    const handleLogin = () => {
        console.log('Переход на страницу логина');
        // Здесь будет вызов API или переход на страницу логина
    };

    const handleSignUp = () => {
        console.log('Переход на страницу регистрации');
        // Здесь будет вызов API или переход на страницу регистрации
    };
        
    return (
        <div className="auth-buttons">
                <div className="auth-buttons-container">
                    <button onClick={handleLogin} className="login-btn">
                        Log In
                    </button>
                    <button onClick={handleSignUp} className="signup-btn">
                        Sign Up
                    </button>
                </div>
        </div>
    );
};

export default AuthButtons;
